		// previous render (e.g. when `setState` is called during render). Drop
		// the effects that render scheduled and restore every hook which
		// compares arguments (effects, ref, memo and callback hooks) to the
		// state it had when the last render was committed, so that effects and
		// memoization are only recomputed when their arguments actually
		// changed since that commit.
		hooks._list.forEach(hookItem => {
			if (hookItem._type >= TYPE_USE_EFFECT && hookItem._type <= TYPE_USE_CALLBACK) {
				hookItem._args = hookItem._committedArgs;
				hookItem._value = hookItem._committedValue;
