export type HookState =
	| EffectHookState
	| MemoHookState
	| ReducerHookState
	| ContextHookState
	| ErrorBoundaryHookState;

export interface CommittedHookState {
	/** The hook type this state was created for */
	_type?: number;
	/** The args as of the last committed render */
	_committedArgs?: any[];
	/** The value as of the last committed render */
	_committedValue?: any;
}

export type Effect = () => void | Cleanup;
export type Cleanup = () => void;

export interface EffectHookState extends CommittedHookState {
	_value?: Effect;
	_args?: any[];
	_cleanup?: Cleanup | void;
}

export interface MemoHookState extends CommittedHookState {
	_value?: any;
	_args?: any[];
	_factory?: () => any;
}

