import { expect } from 'chai';
import { render, act } from 'preact/test-utils';
import { createElement as h } from 'preact';
import { useState, useEffect } from 'preact/hooks';
import { setupRerender } from 'preact/test-utils';

describe('issue repro', () => {
	let scratch;
	let rerender;

	beforeEach(() => {
		scratch = document.createElement('div');
		document.body.appendChild(scratch);
		rerender = setupRerender();
	});

	afterEach(() => {
		scratch.remove();
	});

	it('does not run cleanup when state settles via setA(false) during render', () => {
		const calls = [];
		let setA;
		const Foo = () => {
			const [a, set] = useState(false);
			setA = set;

			useEffect(() => {
				calls.push('effect');
				return () => {
					calls.push('cleanup');
				};
			}, []);

			set(false);

			return <button onClick={() => set(true)}>Hi</button>;
		};

		act(() => {
			render(<Foo />, scratch);
		});
		expect(calls).to.deep.equal(['effect']);

		act(() => {
			setA(true);
		});
		expect(calls).to.deep.equal(['effect']);

		act(() => {
			setA(false);
		});
		expect(calls).to.deep.equal(['effect']);
	});
});

